from collections import deque


def transform(grid):
    """Fill every background component enclosed by the non-background outline with 4."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    seen = [[False] * w for _ in range(h)]
    result = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            component = []
            touches_edge = False
            while q:
                y, x = q.popleft()
                component.append((y, x))
                if y == 0 or y == h - 1 or x == 0 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == background:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if not touches_edge:
                for y, x in component:
                    result[y][x] = 4
    return result
